head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.cnt = 0;
scwin.prevRow = -1;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        $c.cm.PanelToGroupBox(panel_2);

        // fn_setFromToDate(1, edt_pWRT_DD_SDATE, edt_pWRT_DD_EDATE);

        ins_combo_set(dts_DNLD_INST_TP_CD, "ULDINS26500.xml", SCREN_PROCS_TP_CD_01, "03457", "ALL");
        ins_combo_set(dts_APPL_PROCS_TP_CD, "ULDINS26500.xml", SCREN_PROCS_TP_CD_01, "03398", "ALL");
        ins_combo_set(dts_DNLD_GRP_TP_CD, "ULDINS26500.xml", SCREN_PROCS_TP_CD_01, "04204", "NODEFAULT"); // 다운로드그룹구분

        if (document.getElementById("btn_save")) {
            btn_save.setDisabled(true);
            btn_save.src = "../img/ins/btn_down.gif";
        }
        if (document.getElementById("btn_ret")) {
            btn_ret.setDisabled(true); // 반송
            btn_ret.src = "../img/ins/btn_Ret_d.gif";
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS26500.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_pWRT_DD_SDATE_onclick
 * @description img_pWRT_DD_SDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_pWRT_DD_SDATE_onclick = function() {
    try {
        popUpCalendar2(edt_pWRT_DD_SDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS26500.img_pWRT_DD_SDATE_onclick" });
    }
};

/**
 * @method
