/**
 * @method
 * @name trs_save_OnSuccess
 * @description save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "다운로드 관리"));
        await scwin.ins_search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS26500.trs_save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_save_OnFail
 * @description save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_save_OnFail = function() {
    try {
        alert_tr_error(trs_save);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS26500.trs_save_OnFail" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_List.errorMsg) {
            await $c.win.alert(dts_List.errorMsg);
        } else {
            txb_TotalCnt.setValue("총 " + rowcount + "건");
        }
        scwin.cnt = rowcount;

        if (document.getElementById("btn_save")) {
            btn_save.setDisabled(true);
            btn_save.src = "../img/ins/btn_down_d.gif";
        }
        if (document.getElementById("btn_ret")) {
            btn_ret.setDisabled(true); // 반송
            btn_ret.src = "../img/ins/btn_Ret_d.gif";
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS26500.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_search_onclick
 * @description btn_search 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function() {
    try {
        await scwin.ins_search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS26500.btn_search_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
        scwin.cnt = 0;

        if (document.getElementById("btn_save")) {
            btn_save.setDisabled(true);
            btn_save.src = "../img/ins/btn_down_d.gif";
        }
        if (document.getElementById("btn_ret")) {
            btn_ret.setDisabled(true); // 반송
            btn_ret.src = "../img/ins/btn_Ret_d.gif";
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS26500.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnRowPosChanged
 * @description List On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnRowPosChanged = function(row) {
    try {
        if (dts_List.getRowStatus(row) === 1) return;
        dts_List.undoRow(scwin.prevRow);
        scwin.prevRow = row;
        if (document.getElementById("btn_save")) {
            btn_save.setDisabled(false);
            btn_save.src = "../img/ins/btn_down.gif";
        }
        if (document.getElementById("btn_ret")) {
            btn_ret.setDisabled(false); // 반송
            btn_ret.src = "../img/ins/btn_Ret.gif";
        }
        const nRow = dts_List.getRowPosition();
        if (dts_List.getCellData(nRow, "APPL_PROCS_TP_CD") === "3") {
            btn_ret.setDisabled(true); // 반송
            btn_ret.src = "../img/ins/btn_Ret_d.gif";
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS26500.dts_List_OnRowPosChanged" });
    }
};

/**
 * @method
 * @name btn_ret_onclick
 * @description btn_ret 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ret_onclick = function() {
    try {
        ins_popupOpen("", "", "ULDINS93910", "반송처리", "460", "120");
        // ins_retrun();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS26500.btn_ret_onclick" });
    }
};

/**
 * @method
 * @name txb_pWRTR_NM_onkeyup
 * @description txb_pWRTR_NM 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_pWRTR_NM_onkeyup = async function() {
    try {
        fn_DelChar(this);
        if (txb_pWRTR_NM.getValue() === "") {

        } else {
            if (window.event.keyCode === 13) {
                await scwin.ins_search();
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS26500.txb_pWRTR_NM_onkeyup" });
    }
};

