///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_search
 * @description 다운로드 관리목록 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    // 데이터셋 초기화
    dts_List.removeAll();

    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_process
 * @description 다운로드 관리저장 , 수정 한다. screenProcsTpCd 02,03
 * @param {String} screenProcsTpCd screenProcsTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_process = async function(screenProcsTpCd) {
    if (screenProcsTpCd === '03') {
        // 수정

        dts_List.setCellData(dts_List.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
        if (!confirm('다운로드 관리 내용을 처리완료 하시겠습니까?')) {
            return false;
        }
        trs_save.KeyName = "toinb_dataid4";
        // [전환검토] trs_save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     EMP_NO : js_emp_no,
        //     EMP_NM : "관리자",
        //     EMAIL : "listing2@krx.co.kr"
        // };
        const sbmOptions = {
            id : "sbm_trs_save",
            action : "/DownLoadInfoAction.do",
            ref : "dts_List",
            target : "trs_save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name ins_retrun
 * @description 다운로드관리 반송처리 한다. screenProcsTpCd 02,03
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_retrun = async function() {
    dts_List.setCellData(dts_List.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    if (txb_RET_RSN.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "반송사유"));
        txb_RET_RSN.focus();
        return false;
    }
    if (!confirm('다운로드 관리 내용을 반송 하시겠습니까?')) {
        return false;
    }
    trs_save.KeyName = "toinb_dataid4";
    // [전환검토] trs_save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : "관리자",
    //     EMAIL : "listing2@krx.co.kr"
    // };
    const sbmOptions = {
        id : "sbm_trs_save",
        action : "/DownLoadInfoAction.do",
        ref : "dts_List",
        target : "trs_save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};
